    $src =~ s{//[^\n]*}{}g;

    my $pkg = "unknown";
    if ($src =~ /^\s*package\s+(\w+)/m) { $pkg = $1; }

    # Match func declarations. Handle multi-line signatures by scanning.
    # func Name(
    # func (recv Type) Name(
    # func (recv *Type) Name(
    pos($src) = 0;
    while ($src =~ /\bfunc\s+/g) {
        my $after = substr($src, pos($src), 400);
        my $recv = "";
        my $name = "";
