use strict;
use warnings;
use File::Find;

my $root = "/bench/repo";

# Collect all go files
my @gofiles;
find(sub {
    return unless /\.go$/;
    return if $File::Find::name =~ m{/\.git/};
    push @gofiles, $File::Find::name;
}, $root);

# Map: file -> {pkg, imports, is_test, path, src}
# imports: alias -> import_path

sub strip_comments {
    my ($s) = @_;
    $s =~ s{/\*.*?\*/}{}sg;
    $s =~ s{//[^\n]*}{}g;
    return $s;
}

sub parse_file {
    my ($file) = @_;
    open my $in, '<', $file or die $!;
    my $raw = do { local $/; <$in> };
    close $in;
    my $src = strip_comments($raw);
    my $pkg = "unknown";
    if ($src =~ /^\s*package\s+(\w+)/m) { $pkg = $1; }

    my %imports;
    # import "path"
    while ($src =~ /import\s+"([^"]+)"/g) {
        my $path = $1;
        my $alias = $path;
        $alias =~ s{.*/}{};
        $imports{$alias} = $path;
    }
    # import ( ... )
    if ($src =~ /import\s*\((.*?)\)/s) {
        my $block = $1;
        for my $line (split /\n/, $block) {
            $line =~ s/^\s+|\s+$//g;
            next unless $line;
            if ($line =~ /^(\w+)\s+"([^"]+)"/) {
                $imports{$1} = $2;
            } elsif ($line =~ /^_\s+"([^"]+)"/) {
                # blank import
            } elsif ($line =~ /^\.\s+"([^"]+)"/) {
                $imports{"."} = $1; # rare
            } elsif ($line =~ /^"([^"]+)"/) {
                my $path = $1;
                my $alias = $path;
                $alias =~ s{.*/}{};
                $imports{$alias} = $path;
            }
        }
    }
    return {
        file => $file,
        pkg => $pkg,
        src => $src,
        imports => \%imports,
        is_test => ($file =~ /_test\.go$/ ? 1 : 0),
    };
}

# Collect declarations under internal/ (non-test first; also track tests)
my @decls;
for my $file (@gofiles) {
    next unless $file =~ m{/internal/};
    next if $file =~ /_test\.go$/;
    my $info = parse_file($file);
    my $src = $info->{src};
    my $pkg = $info->{pkg};
    # derive import path
    my $rel = $file;
    $rel =~ s{^\Q$root\E/}{};
    $rel =~ s{/[^/]+$}{}; # directory
    my $import_path = "github.com/usememos/memos/" . $rel;

    pos($src) = 0;
    while ($src =~ /\bfunc\s+/g) {
        my $after = substr($src, pos($src), 500);
        my $recv = "";
        my $name = "";
        if ($after =~ /^\(([^)]*)\)\s*(\w+)\s*\(/s) {
            $recv = $1;
            $name = $2;
        } elsif ($after =~ /^(\w+)\s*\(/s) {
            $name = $1;
        } else {
            next;
        }
        next if $name eq "" or $name eq "init";
        $recv =~ s/\s+/ /g;
        # extract receiver type
        my $rtype = "";
        if ($recv =~ /\*?(\w+)\s*$/) { $rtype = $1; }
        push @decls, {
            pkg => $pkg,
            name => $name,
            recv => $recv,
            rtype => $rtype,
            is_method => ($recv ne "" ? 1 : 0),
            file => $file,
            import_path => $import_path,
            rel => $rel,
        };
    }
}

print "DECLS: " . scalar(@decls) . "\n";

# Parse all files once
my @parsed;
for my $file (@gofiles) {
    push @parsed, parse_file($file);
}

# Count call sites for each declaration
# For functions: 
#   - same package: \bName(  (not after a dot)
#   - imported: \balias.Name(
# For methods:
#   - \.Name(  (any selector call) — noisy
# We'll count functions more accurately and methods separately

# Token-ish call finder
sub count_func_calls {
    my ($info, $decl) = @_;
    my $src = $info->{src};
    my $name = $decl->{name};
    my $count = 0;
    my $same_pkg = ($info->{pkg} eq $decl->{pkg} && $info->{file} =~ m{/internal/} 
                    && dirname_of($info->{file}) eq dirname_of($decl->{file}));
    # more reliable same package: same import path directory
    my $fdir = $info->{file}; $fdir =~ s{/[^/]+$}{};
    my $ddir = $decl->{file}; $ddir =~ s{/[^/]+$}{};
    $same_pkg = ($fdir eq $ddir);

    my $imported_alias;
    for my $alias (keys %{$info->{imports}}) {
        if ($info->{imports}{$alias} eq $decl->{import_path}) {
            $imported_alias = $alias;
        }
    }

    if ($same_pkg) {
        # Count Name( not preceded by . or ident.
        while ($src =~ /(?:^|[^.\w])\b\Q$name\E\s*\(/g) {
            $count++;
        }
        # subtract the declaration itself (func Name()
        $count-- if $src =~ /\bfunc\s+\Q$name\E\s*\(/;
        $count = 0 if $count < 0;
    }
    if (defined $imported_alias) {
        while ($src =~ /\b\Q$imported_alias\E\.\Q$name\E\s*\(/g) {
            $count++;
        }
    }
    return $count;
}

sub dirname_of {
    my $f = shift;
    $f =~ s{/[^/]+$}{};
    return $f;
}

sub count_method_calls {
    my ($info, $decl) = @_;
    my $src = $info->{src};
    my $name = $decl->{name};
    my $count = 0;
    # Only count in files that could know about this type:
    # - same package
    # - files that import the package (external callers using exported methods)
    my $fdir = $info->{file}; $fdir =~ s{/[^/]+$}{};
    my $ddir = $decl->{file}; $ddir =~ s{/[^/]+$}{};
    my $same_pkg = ($fdir eq $ddir);
    my $imported = 0;
    for my $alias (keys %{$info->{imports}}) {
        $imported = 1 if $info->{imports}{$alias} eq $decl->{import_path};
    }
    return 0 unless $same_pkg || $imported;

    # Count .Name(
    while ($src =~ /\.\Q$name\E\s*\(/g) {
        $count++;
    }
    return $count;
}

# Score all decls
my @results;
for my $d (@decls) {
    my $sites = 0;
    my $sites_notest = 0;
    my $files = 0;
    my $files_notest = 0;
    my %caller_funcs;
    for my $info (@parsed) {
        my $c;
        if ($d->{is_method}) {
            $c = count_method_calls($info, $d);
        } else {
            $c = count_func_calls($info, $d);
        }
        if ($c > 0) {
            $sites += $c;
            $files++;
            unless ($info->{is_test}) {
                $sites_notest += $c;
                $files_notest++;
            }
        }
    }
    push @results, {
        d => $d,
        sites => $sites,
        sites_notest => $sites_notest,
        files => $files,
        files_notest => $files_notest,
    };
}

# Sort by sites desc
@results = sort { $b->{sites} <=> $a->{sites} || $b->{sites_notest} <=> $a->{sites_notest} } @results;

print "\n=== TOP 40 by call sites (incl tests) ===\n";
printf "%-8s %-8s %-6s %-6s %-8s %-30s %s\n", "sites", "noTest", "files", "fNT", "method", "symbol", "path";
for my $i (0..39) {
    last if $i > $#results;
    my $r = $results[$i];
    my $d = $r->{d};
    my $sym = $d->{is_method} ? "$d->{pkg}.$d->{rtype}.$d->{name}" : "$d->{pkg}.$d->{name}";
    my $rel = $d->{file}; $rel =~ s{^\Q$root\E/}{};
    printf "%-8d %-8d %-6d %-6d %-8s %-30s %s\n",
        $r->{sites}, $r->{sites_notest}, $r->{files}, $r->{files_notest},
        ($d->{is_method} ? "M" : "F"), $sym, $rel;
}

print "\n=== TOP 20 functions only (not methods) ===\n";
my @funcs = grep { !$_->{d}{is_method} } @results;
@funcs = sort { $b->{sites} <=> $a->{sites} } @funcs;
for my $i (0..19) {
    last if $i > $#funcs;
    my $r = $funcs[$i];
    my $d = $r->{d};
    my $rel = $d->{file}; $rel =~ s{^\Q$root\E/}{};
    printf "%-8d %-8d %-30s %s\n", $r->{sites}, $r->{sites_notest}, "$d->{pkg}.$d->{name}", $rel;
}
ENDSCRIPT
