                $fname = "$rt.$n";
            } elsif ($after =~ /^(\w+)/) {
                $fname = $1;
            }
            push @funcs, [$fpos, $fname];
        }

        for my $p (@positions) {
            my $caller = "<file-level>";
            for my $i (0..$#funcs) {
                if ($funcs[$i][0] <= $p && ($i == $#funcs || $funcs[$i+1][0] > $p)) {
                    $caller = $funcs[$i][1];
                    last;
                }
            }
            my $rel = $file; $rel =~ s{^\Q$root\E/}{};
            my $key = "$rel:$caller";
            $callers{$key}++;
            $callers_prod{$key}++ unless $is_test;
        }
    }

    printf "\n==== %s ====\n", $label;
    printf "sites=%d sites_prod=%d unique_callers=%d unique_callers_prod=%d files=%d files_prod=%d\n",
        $sites, $sites_prod, scalar(keys %callers), scalar(keys %callers_prod),
        scalar(keys %files), scalar(keys %files_prod);
    print "callers:\n";
    for my $k (sort keys %callers) {
        printf "  %3d  %s%s\n", $callers{$k}, $k, ($callers_prod{$k} ? "" : " [test]");
    }
}
