use strict;
use warnings;

my $root = "/bench/repo";
my @gofiles;
open my $fh, '-|', "find $root -name '*.go' -not -path '*/.git/*'" or die $!;
while (<$fh>) { chomp; push @gofiles, $_; }
close $fh;

sub strip_comments {
    my ($s) = @_;
    $s =~ s{/\*.*?\*/}{}sg;
    $s =~ s{//[^\n]*}{}g;
    return $s;
}

sub parse_file {
    my ($file) = @_;
    open my $in, '<', $file or die $!;
    my $raw = do { local $/; <$in> };
    close $in;
    my $src = strip_comments($raw);
    my $pkg = "unknown";
    if ($src =~ /^\s*package\s+(\w+)/m) { $pkg = $1; }
    my %imports;
    while ($src =~ /import\s+"([^"]+)"/g) {
        my $path = $1; my $alias = $path; $alias =~ s{.*/}{};
        $imports{$alias} = $path;
    }
    if ($src =~ /import\s*\((.*?)\)/s) {
        for my $line (split /\n/, $1) {
            $line =~ s/^\s+|\s+$//g; next unless $line;
            if ($line =~ /^(\w+)\s+"([^"]+)"/) { $imports{$1} = $2; }
            elsif ($line =~ /^"([^"]+)"/) { my $p=$1; my $a=$p; $a=~s{.*/}{}; $imports{$a}=$p; }
        }
    }
    # function ranges
    my @funcs;
    pos($src) = 0;
    while ($src =~ /\bfunc\s+/g) {
        my $fpos = $-[0];
        my $after = substr($src, pos($src), 400);
        my $fname = "?";
        my $recv = "";
        if ($after =~ /^\(([^)]*)\)\s*(\w+)/s) {
            $recv = $1; my $n = $2;
            $recv =~ s/\s+/ /g;
            my $rt = ""; $rt = $1 if $recv =~ /\*?(\w+)\s*$/;
            $fname = "$rt.$n";
        } elsif ($after =~ /^(\w+)/) {
            $fname = $1;
        }
        push @funcs, [$fpos, $fname];
    }
    return { file=>$file, pkg=>$pkg, src=>$src, imports=>\%imports,
             is_test=>($file=~/_test\.go$/?1:0), funcs=>\@funcs };
}

my @parsed = map { parse_file($_) } @gofiles;

# decls from internal non-test
my @decls;
for my $info (@parsed) {
    next unless $info->{file} =~ m{/internal/};
    next if $info->{is_test};
    my $rel = $info->{file}; $rel =~ s{^\Q$root\E/}{};
    my $dir = $rel; $dir =~ s{/[^/]+$}{};
    my $ip = "github.com/usememos/memos/$dir";
    for my $fn (@{$info->{funcs}}) {
        my $name = $fn->[1];
        next if $name eq "?" or $name eq "init";
        my $is_method = ($name =~ /\./) ? 1 : 0;
        my $simple = $name;
        $simple =~ s/^.*\.//;
        next if $simple eq "init";
        push @decls, {
            pkg => $info->{pkg},
            full => ($is_method ? "$info->{pkg}.$name" : "$info->{pkg}.$name"),
            simple => $simple,
            is_method => $is_method,
            file => $info->{file},
            import_path => $ip,
            decl_pos => $fn->[0],
        };
    }
}

sub dir_of { my $f=shift; $f=~s{/[^/]+$}{}; $f }

my @results;
for my $d (@decls) {
    my $sites=0; my $sites_prod=0;
    my %callers; my %callers_prod;
    my $simple = $d->{simple};

    for my $info (@parsed) {
        my $fdir = dir_of($info->{file});
        my $ddir = dir_of($d->{file});
        my $same = ($fdir eq $ddir);
        my $imported_alias;
        for my $a (keys %{$info->{imports}}) {
            $imported_alias = $a if $info->{imports}{$a} eq $d->{import_path};
        }

        my @pos;
        if ($d->{is_method}) {
            next unless $same || defined $imported_alias;
            while ($info->{src} =~ /\.\Q$simple\E\s*\(/g) {
                push @pos, $-[0];
            }
        } else {
            if ($same) {
                while ($info->{src} =~ /(?:^|[^.\w])\b\Q$simple\E\s*\(/g) {
                    my $p = $-[0];
                    # skip declaration
                    my $around = substr($info->{src}, ($p>5?$p-5:$p), 20);
                    next if $info->{src} =~ /\G/;
                    # check if this is the func declaration
                    my $prefix = substr($info->{src}, ($p>10?$p-10:$p), 30);
                    next if $prefix =~ /func\s+\Q$simple\E/;
                    push @pos, $p;
                }
            }
            if (defined $imported_alias) {
                while ($info->{src} =~ /\b\Q$imported_alias\E\.\Q$simple\E\s*\(/g) {
                    push @pos, $-[0];
                }
            }
        }
        next unless @pos;

        for my $p (@pos) {
            $sites++;
            $sites_prod++ unless $info->{is_test};
            my $caller = "<file>";
            my $funcs = $info->{funcs};
            for my $i (0..$#$funcs) {
                if ($funcs->[$i][0] <= $p && ($i==$#$funcs || $funcs->[$i+1][0] > $p)) {
                    $caller = $funcs->[$i][1];
                    last;
                }
            }
            # skip if this "call" is the declaration itself
            if ($same && $caller eq ($d->{is_method} ? ($d->{full}=~/\.([^.]+)$/, "$1") : $d->{simple})) {
                # still might be recursive call; only skip if very close to decl
            }
            my $rel = $info->{file}; $rel =~ s{^\Q$root\E/}{};
            my $key = "$rel:$caller";
            $callers{$key}++;
            $callers_prod{$key}++ unless $info->{is_test};
        }
    }
    push @results, {
        d=>$d, sites=>$sites, sites_prod=>$sites_prod,
        callers=>scalar(keys %callers), callers_prod=>scalar(keys %callers_prod),
    };
}

print "=== TOP 20 by unique callers (incl tests) ===\n";
my @byc = sort { $b->{callers} <=> $a->{callers} || $b->{sites} <=> $a->{sites} } @results;
for my $i (0..19) {
    my $r = $byc[$i];
